<?php
function beheerChangelogMagOpenen(): bool { if (empty($GLOBALS['ingelogd'])) return false; if (!empty($GLOBALS['isMaster'])) return true; return in_array('changelog', (array)($GLOBALS['toegestaneTabs'] ?? []), true); }
function beheerChangelogBewaakLegacyPost(): void { if (($_SERVER['REQUEST_METHOD'] ?? '') !== 'POST') return; $f=(string)($_POST['formulier'] ?? ''); if(!in_array($f,['changelog_toevoegen','changelog_bewerken','changelog_verwijderen'],true))return; $_POST['formulier']=''; if(function_exists('schrijfLog')) schrijfLog($GLOBALS['logBestand'],$GLOBALS['huidigeGebruiker'],'legacy_changelog_geblokkeerd',$f); }
function beheerChangelogStartOutputFilter(): void { ob_start(function($html){ if(!is_string($html))return $html; if(beheerChangelogMagOpenen())$html=preg_replace('~<button\s+type="button"\s+class="menu-item"\s+data-tab="changelog">.*?</button>~is','<a class="menu-item menu-item-link" style="display:block;text-decoration:none" href="changelog.php">* Changelog</a>',$html,1)??$html; if(stripos($html,'</head>')!==false)$html=preg_replace('~</head>~i','<style>#tab-changelog{display:none!important}</style></head>',$html,1)??$html; return $html;}); }
beheerChangelogBewaakLegacyPost(); beheerChangelogStartOutputFilter();
